insert into topic_contents (topic_id, summary, content_md, example_question) values ('73d24254-55ed-43ae-8627-1456e48059b4', 'Türkiye''nin matematik konumu (enlem-boylam) ile özel konumu (yakın çevre ilişkileri) birbirinden ayrı sonuçlar doğurur; KPSS bu iki kavramı ve sonuçlarını karıştırmadan ayırt edebilmeyi ölçer.', '## Matematik Konum ve Sonuçları
insert into questions (id, topic_id, difficulty, question_text, kazanim, explanation) values ('60432c81-98e2-422e-bb1c-91d668b9d77c', '73d24254-55ed-43ae-8627-1456e48059b4', 'kolay'::difficulty_level, 'Türkiye''nin matematik konumunun bir sonucu olarak aşağıdakilerden hangisi gösterilebilir?', 'Matematik konumun sonuçlarını ayırt eder.', 'Yerel saat farkı doğrudan enlem-boylam konumuna, yani matematik konuma bağlıdır (B doğru). Komşu sayısı (A), boğazların önemi (C), turizm çeşitliliği (D) ve ticaret yollarının üzerinde bulunma (E) özel konumun sonuçlarıdır; beşerî/siyasi ilişkilerle ilgilidir, enlem-boylamla değil.');
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('60432c81-98e2-422e-bb1c-91d668b9d77c', 'Sekiz komşu ülkeye sahip olması', false, 0);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('60432c81-98e2-422e-bb1c-91d668b9d77c', 'Doğu ile batı arasında yerel saat farkının bulunması', true, 1);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('60432c81-98e2-422e-bb1c-91d668b9d77c', 'İstanbul ve Çanakkale Boğazlarının jeopolitik öneme sahip olması', false, 2);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('60432c81-98e2-422e-bb1c-91d668b9d77c', 'Turizm gelirlerinin çeşitlilik göstermesi', false, 3);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('60432c81-98e2-422e-bb1c-91d668b9d77c', 'Önemli ticaret yolları üzerinde bulunması', false, 4);
insert into questions (id, topic_id, difficulty, question_text, kazanim, explanation) values ('3ab1fc08-0722-4471-85b6-70385dec62ce', '73d24254-55ed-43ae-8627-1456e48059b4', 'orta'::difficulty_level, 'Aşağıdakilerden hangisi Türkiye''nin özel konumunun bir sonucu değildir?', 'Özel konum sonuçlarını matematik konum sonuçlarından ayırt eder.', 'Gölge boylarının mevsimden mevsime değişmesi, güneş ışınlarının geliş açısındaki (yani enlem/matematik konumdaki) değişime bağlıdır (E doğru, bu bir özel konum sonucu DEĞİLDİR). Üç kıtaya yakınlık (A), boğazların önemi (B), 8 komşu (C) ve ticaret yollarının kesişmesi (D) özel konumun tipik sonuçlarıdır.');
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('3ab1fc08-0722-4471-85b6-70385dec62ce', 'Üç kıtaya yakın olması', false, 0);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('3ab1fc08-0722-4471-85b6-70385dec62ce', 'Boğazların jeopolitik açıdan önemli olması', false, 1);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('3ab1fc08-0722-4471-85b6-70385dec62ce', 'Sekiz ülkeyle komşu olması', false, 2);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('3ab1fc08-0722-4471-85b6-70385dec62ce', 'Kara, demir ve boru hattı ticaret yollarının kesişim noktasında bulunması', false, 3);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('3ab1fc08-0722-4471-85b6-70385dec62ce', 'Gölge boylarının mevsimden mevsime değişmesi', true, 4);
