insert into questions (id, topic_id, difficulty, question_text, kazanim, explanation) values ('4a51bc7f-ca78-4090-960c-631569937f22', '73d24254-55ed-43ae-8627-1456e48059b4', 'orta'::difficulty_level, 'Türkiye''nin sınırlarının uzunluğu ve komşu ülke sayısının fazla olması, aşağıdaki konum unsurlarından hangisiyle açıklanır?', 'Sınır ve komşuluk ilişkilerini konum unsurlarıyla ilişkilendirir.', 'Sınır uzunluğu ve komşu ülke sayısı, ülkenin coğrafi olarak hangi bölgede, hangi devletlerle çevrili olduğuyla ilgili olduğu için özel konumun bir sonucudur (B doğru). Matematik konum (A) enlem-boylama bağlı sonuçları (yerel saat, mevsimler) ifade eder ve sınır/komşuluk ile doğrudan ilgili değildir. C, D, E seçenekleri konu dışı, anlamsız çeldiricilerdir.');
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('4a51bc7f-ca78-4090-960c-631569937f22', 'Matematik konum', false, 0);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('4a51bc7f-ca78-4090-960c-631569937f22', 'Özel konum', true, 1);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('4a51bc7f-ca78-4090-960c-631569937f22', 'Yerel saat farkı', false, 2);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('4a51bc7f-ca78-4090-960c-631569937f22', 'Gölge boyu uzunluğu', false, 3);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('4a51bc7f-ca78-4090-960c-631569937f22', 'Güneş ışınlarının geliş açısı', false, 4);
insert into topic_contents (topic_id, summary, content_md, example_question) values ('f4bdef2c-d148-4d88-832f-731b8e3d122c', 'Türkiye''de görülen dört büyük iklim tipinin (Karadeniz, Akdeniz, karasal, Marmara geçiş) yağış rejimi, sıcaklık özellikleri ve görüldüğü bölgeler; bu tiplerin birbirinden ayırt edilmesi KPSS''de en sık sorulan alt başlıktır.', '## Karadeniz İklimi
insert into questions (id, topic_id, difficulty, question_text, kazanim, explanation) values ('c70f3a79-658f-41e6-8736-1266871c103f', 'f4bdef2c-d148-4d88-832f-731b8e3d122c', 'kolay'::difficulty_level, 'Her mevsim yağışlı olan, yazın en yağışlı mevsim olduğu iklim tipi aşağıdakilerden hangisidir?', 'İklim tiplerinin yağış rejimi özelliklerini bilir.', 'Karadeniz iklimi, Türkiye''de yaz kuraklığının görülmediği tek iklim tipidir; her mevsim yağış alır ve en fazla yağış yaz aylarında düşer (A doğru). Akdeniz (B) yazın kurak, kışın yağışlıdır. Karasal iklim (C) yazın kurak geçer. Marmara (D) geçiş özelliği taşır ama Karadeniz kadar dengeli değildir. Muson iklimi (E) Türkiye''de görülmez, bu bir çeldiricidir.');
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('c70f3a79-658f-41e6-8736-1266871c103f', 'Karadeniz iklimi', true, 0);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('c70f3a79-658f-41e6-8736-1266871c103f', 'Akdeniz iklimi', false, 1);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('c70f3a79-658f-41e6-8736-1266871c103f', 'Karasal iklim', false, 2);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('c70f3a79-658f-41e6-8736-1266871c103f', 'Marmara (geçiş) iklimi', false, 3);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('c70f3a79-658f-41e6-8736-1266871c103f', 'Muson iklimi', false, 4);
insert into questions (id, topic_id, difficulty, question_text, kazanim, explanation) values ('1281007a-bc8f-40ed-b9d5-e4e5091b05a0', 'f4bdef2c-d148-4d88-832f-731b8e3d122c', 'orta'::difficulty_level, 'Aşağıdaki iklim-bitki örtüsü eşleştirmelerinden hangisi yanlıştır?', 'İklim tiplerini karakteristik bitki örtüleriyle eşleştirir.', 'Karasal iklimin doğal bitki örtüsü step (bozkır)tir, orman DEĞİLDİR (D yanlış ve sorunun cevabı) — orman, nemli/yağışlı iklimlerin (Karadeniz, Marmara) tipik bitki örtüsüdür. Karadeniz-orman (A), Akdeniz-maki (B) ve Marmara-karışık orman+maki (C) eşleştirmeleri doğrudur. E seçeneği (step-kurakçıl bitkiler) de doğrudur, karasal iklimle tutarlıdır ama soru ''yanlış'' eşleştirmeyi sorduğu için D cevaptır.');
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('1281007a-bc8f-40ed-b9d5-e4e5091b05a0', 'Karadeniz iklimi – gür orman', false, 0);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('1281007a-bc8f-40ed-b9d5-e4e5091b05a0', 'Akdeniz iklimi – maki', false, 1);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('1281007a-bc8f-40ed-b9d5-e4e5091b05a0', 'Marmara (geçiş) iklimi – karışık orman ve maki', false, 2);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('1281007a-bc8f-40ed-b9d5-e4e5091b05a0', 'Karasal iklim – gür orman', true, 3);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('1281007a-bc8f-40ed-b9d5-e4e5091b05a0', 'Karasal iklim – step (bozkır)', false, 4);
insert into questions (id, topic_id, difficulty, question_text, kazanim, explanation) values ('3b6e9fcb-fb85-4d1f-8012-c08aaad6f8b6', 'f4bdef2c-d148-4d88-832f-731b8e3d122c', 'zor'::difficulty_level, 'Aşağıdaki haritada A ve B noktaları Türkiye''nin farklı kıyı kesimlerinde yer almaktadır. A noktasında yıllık yağış miktarı 2000 mm''nin üzerindeyken, aynı iklim tipinin görüldüğü B noktasında bu miktar 700 mm civarındadır. Bu farkın en önemli nedeni aşağıdakilerden hangisidir?', 'Aynı iklim tipi içindeki yağış miktarı farklarını bakı ve dağların uzanış doğrultusuyla ilişkilendirir.', 'Karadeniz kıyısında yağış miktarındaki bu tür büyük farklar, dağların kıyıya paralel uzanması ve nemli hava kütlelerinin karşılaştığı yamaçların bakı (güneşe/denize bakma) durumuna bağlıdır; Doğu Karadeniz''de dağlar denize daha dik/yakın ve yükselti daha fazla olduğundan yağış miktarı dramatik biçimde artar (D doğru). Enlem farkı (A) bu kısa mesafede ihmal edilebilir düzeydedir. Toprak tipi (B) ve bitki örtüsü yoğunluğu (C) yağışın SONUCUdur, NEDENİ değildir — sebep-sonuç ters çevrilmiştir. Deniz suyu sıcaklığı (E) yağış miktarındaki bu büyüklükte bir farkı açıklayacak temel faktör değildir.');
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('3b6e9fcb-fb85-4d1f-8012-c08aaad6f8b6', 'İki nokta arasındaki enlem farkının çok büyük olması', false, 0);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('3b6e9fcb-fb85-4d1f-8012-c08aaad6f8b6', 'B noktasındaki toprak tipinin farklı olması', false, 1);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('3b6e9fcb-fb85-4d1f-8012-c08aaad6f8b6', 'A noktasındaki bitki örtüsünün daha yoğun olması', false, 2);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('3b6e9fcb-fb85-4d1f-8012-c08aaad6f8b6', 'Dağların kıyıya paralel uzanması ve bakı farkının nemli hava kütlelerinin yükselişini etkilemesi', true, 3);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('3b6e9fcb-fb85-4d1f-8012-c08aaad6f8b6', 'B noktasındaki deniz suyu sıcaklığının daha düşük olması', false, 4);
insert into questions (id, topic_id, difficulty, question_text, kazanim, explanation) values ('af979c88-5085-4f87-ad40-e1cb595da5a1', 'f4bdef2c-d148-4d88-832f-731b8e3d122c', 'orta'::difficulty_level, 'Doğu Anadolu Bölgesi''nde kışların Türkiye''nin geri kalanına göre daha sert ve soğuk geçmesinin temel nedeni aşağıdakilerden hangisidir?', 'Yükseltinin iklim üzerindeki etkisini açıklar.', 'Doğu Anadolu''nun ortalama yükseltisinin Türkiye''nin diğer bölgelerine göre çok daha fazla olması, sıcaklığın yükseklikle birlikte düşmesi (her 200 metrede yaklaşık 1°C azalma) ilkesi gereği kışların olağanüstü sert ve soğuk geçmesine neden olur (B doğru). Enlem farkı (A) tek başına bu kadar büyük bir sıcaklık farkını açıklamaz. Karadeniz''e yakınlık (C) tam tersine ılımanlaştırıcı bir etki yapardı ama dağlar bu etkiyi engeller. Toprak tipi (D) ve bitki örtüsü (E) sıcaklık farkının nedeni değil, iklimin bir sonucudur.');
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('af979c88-5085-4f87-ad40-e1cb595da5a1', 'Enlem derecesinin çok yüksek olması', false, 0);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('af979c88-5085-4f87-ad40-e1cb595da5a1', 'Bölgenin ortalama yükseltisinin fazla olması', true, 1);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('af979c88-5085-4f87-ad40-e1cb595da5a1', 'Karadeniz''e yakın olması', false, 2);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('af979c88-5085-4f87-ad40-e1cb595da5a1', 'Toprak tipinin farklı olması', false, 3);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('af979c88-5085-4f87-ad40-e1cb595da5a1', 'Bitki örtüsünün seyrek olması', false, 4);
insert into topics (id, subject_id, name, slug, kazanim_text, weight, order_index) values ('714f0c66-ba93-4fc8-8b82-9b0800a7350f', 'e096912f-78c9-431d-8a7b-f5b3c005f472', 'Türkiye''nin Yerşekilleri', 'turkiyenin-yersekilleri', 'Türkiye''nin yer şekillerinin oluşumunu ve dağılışını, bunların ekonomik faaliyetlere etkisiyle birlikte açıklar.', 1.0, 6);
insert into topic_contents (topic_id, summary, content_md, example_question) values ('714f0c66-ba93-4fc8-8b82-9b0800a7350f', 'Türkiye''nin dağların kıyıya paralel uzandığı, ortalama yükseltisinin (yaklaşık 1132 m) Avrupa''ya göre yüksek olduğu, III. Jeolojik zamanda oluşan genç ve halen deprem üretebilen bir arazi yapısına sahip olduğu gerçeği; bu konu genellikle deprem, akarsu, ova/plato/dağ ayrımı üzerinden sorulur.', '## Oluşum ve Genel Özellikler
insert into questions (id, topic_id, difficulty, question_text, kazanim, explanation) values ('f0be4e6c-fa70-4728-9ad2-6d10934e78ba', '714f0c66-ba93-4fc8-8b82-9b0800a7350f', 'kolay'::difficulty_level, 'Türkiye''de dağların genel olarak kıyıya paralel uzanmasının en belirgin sonucu aşağıdakilerden hangisidir?', 'Dağların uzanış doğrultusunun ulaşım ve iklime etkisini açıklar.', 'Dağların kıyıya paralel uzanması, kıyı kesimi ile iç kesimler arasındaki ulaşımı zorlaştırır ve denizel iklimin etkisinin iç kesimlere kolayca sokulamamasına neden olur (B doğru). Bu durum akarsu debisiyle (A), toprak verimliliğiyle (C), maden çeşitliliğiyle (D) veya nüfus yoğunluğuyla (E) doğrudan ilgili değildir; bunlar başka etmenlere bağlıdır.');
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('f0be4e6c-fa70-4728-9ad2-6d10934e78ba', 'Akarsuların debisinin artması', false, 0);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('f0be4e6c-fa70-4728-9ad2-6d10934e78ba', 'Kıyı ile iç kesimler arasında ulaşımın zorlaşması', true, 1);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('f0be4e6c-fa70-4728-9ad2-6d10934e78ba', 'Toprakların daha verimli hale gelmesi', false, 2);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('f0be4e6c-fa70-4728-9ad2-6d10934e78ba', 'Maden çeşitliliğinin artması', false, 3);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('f0be4e6c-fa70-4728-9ad2-6d10934e78ba', 'Nüfusun kıyıdan iç kesimlere kaymasının hızlanması', false, 4);
insert into questions (id, topic_id, difficulty, question_text, kazanim, explanation) values ('990ea0e8-a49e-490f-878c-869daebb603e', '714f0c66-ba93-4fc8-8b82-9b0800a7350f', 'orta'::difficulty_level, 'Türkiye''nin yer şekillerinin III. Jeolojik Zamanda oluşmuş genç bir yapıya sahip olmasının doğal bir sonucu aşağıdakilerden hangisidir?', 'Yer şekillerinin oluşum yaşı ile deprem riski arasındaki ilişkiyi açıklar.', 'Genç bir arazi yapısı, fay hatlarının hâlâ aktif olması anlamına gelir; bu da Türkiye''nin önemli bir deprem kuşağında yer almasını doğrudan açıklar (C doğru). Akarsuların debisinin düzenli olması (A) tam tersine yanlıştır, Türkiye akarsuları düzensiz rejimlidir. Ova sayısının azlığı (B), maden yataklarının bulunmayışı (D) ve iklim çeşitliliğinin olmayışı (E) yer şekillerinin gençliğiyle doğrudan ilişkili değildir/gerçeği yansıtmaz.');
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('990ea0e8-a49e-490f-878c-869daebb603e', 'Akarsuların debisinin çok düzenli olması', false, 0);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('990ea0e8-a49e-490f-878c-869daebb603e', 'Ova sayısının ülke genelinde çok az olması', false, 1);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('990ea0e8-a49e-490f-878c-869daebb603e', 'Fay hatlarının hâlâ aktif olması nedeniyle önemli bir deprem kuşağında yer alınması', true, 2);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('990ea0e8-a49e-490f-878c-869daebb603e', 'Maden yataklarının hiç bulunmaması', false, 3);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('990ea0e8-a49e-490f-878c-869daebb603e', 'İklim çeşitliliğinin görülmemesi', false, 4);
