insert into questions (id, topic_id, difficulty, question_text, kazanim, explanation) values ('1412e17d-c371-4a26-ba82-045308e93fc4', '714f0c66-ba93-4fc8-8b82-9b0800a7350f', 'orta'::difficulty_level, 'Türkiye akarsularının ortak özellikleriyle ilgili aşağıdaki ifadelerden hangisi yanlıştır?', 'Türkiye akarsularının genel özelliklerini bilir.', 'Türkiye akarsuları genel olarak eğimin fazla olması nedeniyle hidroelektrik enerji potansiyeli AÇISINDAN ELVERİŞLİDİR; bu yüzden ''hidroelektrik potansiyeli düşüktür'' ifadesi (D) yanlıştır ve sorunun cevabıdır. Kısa boylu olmaları (A), düzensiz rejime/debiye sahip olmaları (B) ve bu yüzden ulaşıma elverişli olmamaları (C) doğru genellemelerdir. Yağış rejimine bağlı olarak debilerinin mevsimden mevsime değişmesi (E) de doğrudur.');
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('1412e17d-c371-4a26-ba82-045308e93fc4', 'Genel olarak kısa boyludurlar', false, 0);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('1412e17d-c371-4a26-ba82-045308e93fc4', 'Debileri (su miktarları) düzensizdir', false, 1);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('1412e17d-c371-4a26-ba82-045308e93fc4', 'Eğimleri fazla olduğu için ulaşıma elverişli değildirler', false, 2);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('1412e17d-c371-4a26-ba82-045308e93fc4', 'Eğimleri fazla olduğu için hidroelektrik potansiyelleri düşüktür', true, 3);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('1412e17d-c371-4a26-ba82-045308e93fc4', 'Debileri yağış rejimine bağlı olarak mevsimden mevsime değişir', false, 4);
insert into topic_contents (topic_id, summary, content_md, example_question) values ('6b76a27b-b27e-4065-8325-d027f3f3377a', 'Türkiye''de nüfusun dağılışını etkileyen doğal (iklim, yer şekilleri, su kaynakları) ve beşerî (sanayi, ulaşım, tarım, turizm) etmenler; nüfus yoğunluğunun kıyı-iç kesim arasındaki dağılımı bu konunun omurgasıdır.', '## Nüfus Dağılışını Etkileyen Doğal Etmenler
insert into questions (id, topic_id, difficulty, question_text, kazanim, explanation) values ('42fcf944-91bf-4249-9251-60b13080fa4d', '6b76a27b-b27e-4065-8325-d027f3f3377a', 'kolay'::difficulty_level, 'Aşağıdakilerden hangisi Türkiye''de nüfus dağılışını etkileyen doğal etmenlerden biri değildir?', 'Doğal ve beşerî nüfus etmenlerini ayırt eder.', 'Sanayileşme düzeyi bir beşerî/ekonomik etmendir, doğal bir etmen değildir (C doğru ve sorunun cevabı). İklim (A), yer şekilleri (B), su kaynaklarına yakınlık (D) ve toprak verimliliği (E) ise doğrudan doğa kaynaklı, doğal etmenlerdir.');
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('42fcf944-91bf-4249-9251-60b13080fa4d', 'İklim koşulları', false, 0);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('42fcf944-91bf-4249-9251-60b13080fa4d', 'Yer şekillerinin engebeliliği', false, 1);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('42fcf944-91bf-4249-9251-60b13080fa4d', 'Sanayileşme düzeyi', true, 2);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('42fcf944-91bf-4249-9251-60b13080fa4d', 'Su kaynaklarına yakınlık', false, 3);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('42fcf944-91bf-4249-9251-60b13080fa4d', 'Toprak verimliliği', false, 4);
insert into questions (id, topic_id, difficulty, question_text, kazanim, explanation) values ('9fc077b9-5ce4-48fe-a486-ab13d636ad06', '6b76a27b-b27e-4065-8325-d027f3f3377a', 'orta'::difficulty_level, 'Doğu Anadolu Bölgesi''nin Türkiye''nin en seyrek nüfuslu bölgelerinden biri olmasının en önemli nedeni aşağıdakilerden hangisidir?', 'Bölgesel nüfus yoğunluğu farklarını doğal etmenlerle ilişkilendirir.', 'Doğu Anadolu''nun sert kara iklimi ve yüksek/engebeli yer şekilleri (yüksek yaylalar, dağlık arazi), tarımsal ve yerleşim koşullarını zorlaştırarak nüfusun seyrek kalmasına neden olan başlıca doğal etmenlerdir (B doğru). Sanayileşme düzeyinin yüksek olması (A) tam tersine yoğun nüfusa yol açardı ve bölge için geçerli değildir. Ulaşım ağının gelişmişliği (C), turizm potansiyelinin yüksek olması (D) ve tarımsal verimin fazla olması (E) de bölgenin gerçek durumunu yansıtmaz; bunlar nüfusu ARTTIRAN etmenlerdir, bölgenin seyrekliğini açıklamaz.');
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('9fc077b9-5ce4-48fe-a486-ab13d636ad06', 'Sanayileşme düzeyinin çok yüksek olması', false, 0);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('9fc077b9-5ce4-48fe-a486-ab13d636ad06', 'Sert kara ikliminin ve engebeli yer şekillerinin egemen olması', true, 1);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('9fc077b9-5ce4-48fe-a486-ab13d636ad06', 'Ulaşım ağının çok gelişmiş olması', false, 2);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('9fc077b9-5ce4-48fe-a486-ab13d636ad06', 'Turizm potansiyelinin çok yüksek olması', false, 3);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('9fc077b9-5ce4-48fe-a486-ab13d636ad06', 'Tarımsal verimliliğin çok fazla olması', false, 4);
insert into questions (id, topic_id, difficulty, question_text, kazanim, explanation) values ('afe0ef73-0a9f-492b-8e01-afe1c2d12ac4', '6b76a27b-b27e-4065-8325-d027f3f3377a', 'zor'::difficulty_level, 'Bir ilin nüfus yoğunluğunun yüksek, ancak yıllık nüfus artış hızının düşük (hatta negatif) olduğu belirlenmiştir. Bu durum aşağıdaki çıkarımlardan hangisiyle en iyi açıklanır?', 'Nüfus yoğunluğu ile nüfus artış hızı kavramlarını ayırt eder.', 'Nüfus yoğunluğu (birim alana düşen kişi sayısı) ile nüfus artış hızı (belirli bir dönemdeki nüfus değişim oranı) birbirinden tamamen farklı kavramlardır; kalabalık/yoğun nüfuslu büyük şehirlerde doğurganlık oranlarının düşük olması ve dışa göçün fazla olması, o ilin YOĞUN olmasına rağmen artış hızının düşük/negatif çıkmasına yol açabilir (C doğru). A ve B kavramları birbirinin yerine geçirilebilir gibi sunduğu için (aynı şey olduklarını iddia ettiği için) yanlıştır. D ve E, verilen bilgiyle çelişen veya konuyla ilgisiz iddialardır.');
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('afe0ef73-0a9f-492b-8e01-afe1c2d12ac4', 'Nüfus yoğunluğu ile nüfus artış hızı aynı kavramdır, bu durum çelişkilidir', false, 0);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('afe0ef73-0a9f-492b-8e01-afe1c2d12ac4', 'Bu durum yalnızca ölçüm hatasından kaynaklanır', false, 1);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('afe0ef73-0a9f-492b-8e01-afe1c2d12ac4', 'Nüfus yoğunluğu ile nüfus artış hızı farklı kavramlardır; yoğun nüfuslu bir yerde doğurganlığın düşük olması bu duruma yol açabilir', true, 2);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('afe0ef73-0a9f-492b-8e01-afe1c2d12ac4', 'Bu il mutlaka bir tarım bölgesidir', false, 3);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('afe0ef73-0a9f-492b-8e01-afe1c2d12ac4', 'Bu durum yalnızca deniz kıyısında bulunan illerde görülebilir', false, 4);
insert into questions (id, topic_id, difficulty, question_text, kazanim, explanation) values ('b656ded9-92c4-4951-9656-409393c52eb1', '6b76a27b-b27e-4065-8325-d027f3f3377a', 'orta'::difficulty_level, 'Antalya ve Muğla gibi illerde yaz aylarında nüfusun geçici olarak önemli ölçüde artması aşağıdaki etmenlerden hangisiyle açıklanır?', 'Turizmin nüfus hareketliliği üzerindeki etkisini açıklar.', 'Antalya ve Muğla gibi illerde yaz aylarındaki geçici nüfus artışı, bu illerin yüksek turizm potansiyeline bağlı olarak yaz mevsiminde çok sayıda turist ve mevsimlik işçi çekmesiyle açıklanır (D doğru). Bu, kalıcı nüfus yoğunluğundan farklı, GEÇİCİ bir nüfus hareketliliğidir. Sanayileşme (A), tarımsal verim (B) ve madencilik (C) bu illerin yaz aylarındaki geçici nüfus artışının temel nedeni değildir; kış turizmi (E) de bu bölgeler için değil, dağlık/karlı bölgeler için geçerlidir.');
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('b656ded9-92c4-4951-9656-409393c52eb1', 'Sanayi tesislerinin yaz aylarında üretimi artırması', false, 0);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('b656ded9-92c4-4951-9656-409393c52eb1', 'Tarımsal üretimin yaz aylarında zirve yapması', false, 1);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('b656ded9-92c4-4951-9656-409393c52eb1', 'Madencilik faaliyetlerinin yaz aylarında hızlanması', false, 2);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('b656ded9-92c4-4951-9656-409393c52eb1', 'Yüksek turizm potansiyeli nedeniyle yaz aylarında yoğun turist ve mevsimlik işçi akını', true, 3);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('b656ded9-92c4-4951-9656-409393c52eb1', 'Kış turizminin yaz aylarında etkisini artırması', false, 4);
insert into topics (id, subject_id, name, slug, kazanim_text, weight, order_index) values ('307f95b7-0c09-47b4-b088-895dba797c11', 'e096912f-78c9-431d-8a7b-f5b3c005f472', 'Ekonomik Coğrafya (Tarım, Sanayi, Ulaşım)', 'ekonomik-cografya-tarim-sanayi-ulasim', 'Türkiye''nin tarım, sanayi, ulaşım ve ticaret faaliyetlerinin bölgesel dağılışını ve bu dağılışı etkileyen etmenleri açıklar.', 1.0, 7);
insert into topic_contents (topic_id, summary, content_md, example_question) values ('307f95b7-0c09-47b4-b088-895dba797c11', 'Türkiye''de tarımsal ürün deseninin iklime bağlı bölgesel farklılığı, sanayinin Marmara''da yoğunlaşma nedenleri ve ulaşım türlerinin (kara, demir, deniz, hava) yer şekilleriyle ilişkisi; KPSS bu üç alanı sıkça ürün-bölge ve sanayi-etken eşleştirmeleriyle sorar.', '## Tarım
insert into questions (id, topic_id, difficulty, question_text, kazanim, explanation) values ('a33cf980-1673-491e-8141-1c417a2b1493', '307f95b7-0c09-47b4-b088-895dba797c11', 'kolay'::difficulty_level, 'Aşağıdaki tarım ürünü - yetiştirildiği bölge eşleştirmelerinden hangisi doğrudur?', 'Tarımsal ürün deseninin bölgesel dağılışını bilir.', 'Çayın en yoğun üretildiği bölge, bol ve düzenli yağış ile asidik toprak yapısı nedeniyle Doğu Karadeniz''dir (B doğru). Turunçgil (A) Karadeniz''de değil Akdeniz-Ege kıyılarında yetişir. Zeytin (C) İç Anadolu''da değil yine Akdeniz-Ege''de yetişir. Buğday (D) Doğu Karadeniz''de değil İç Anadolu''da yaygındır. Pamuk (E) Doğu Anadolu''da değil Çukurova-Ege-GAP bölgelerinde yetiştirilir.');
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('a33cf980-1673-491e-8141-1c417a2b1493', 'Turunçgil – Doğu Karadeniz', false, 0);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('a33cf980-1673-491e-8141-1c417a2b1493', 'Çay – Doğu Karadeniz', true, 1);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('a33cf980-1673-491e-8141-1c417a2b1493', 'Zeytin – İç Anadolu', false, 2);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('a33cf980-1673-491e-8141-1c417a2b1493', 'Buğday – Doğu Karadeniz', false, 3);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('a33cf980-1673-491e-8141-1c417a2b1493', 'Pamuk – Doğu Anadolu', false, 4);
insert into questions (id, topic_id, difficulty, question_text, kazanim, explanation) values ('49b4f1d6-7ca8-4d5b-98d1-6891c1ff8512', '307f95b7-0c09-47b4-b088-895dba797c11', 'orta'::difficulty_level, 'GAP (Güneydoğu Anadolu Projesi) sonrasında Güneydoğu Anadolu''da pamuk üretiminin belirgin biçimde artması aşağıdaki çıkarımlardan hangisini en iyi destekler?', 'Beşerî müdahalelerin (sulama projeleri) doğal sınırlamalar üzerindeki etkisini yorumlar.', 'Bu durum, sulama gibi beşerî bir müdahalenin, bölgenin kurak iklim koşullarından kaynaklanan doğal bir tarımsal sınırlamayı büyük ölçüde aşabildiğini gösterir (C doğru). A yanlıştır çünkü tarımsal üretim iklimden tamamen bağımsız değildir, sulama iklimin OLUMSUZ etkisini azaltmıştır, iklimi anlamsız kılmamıştır. B, D ve E verilen bilgiyle desteklenmeyen, konuyla ilgisiz veya abartılı iddialardır.');
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('49b4f1d6-7ca8-4d5b-98d1-6891c1ff8512', 'Tarımsal üretim tamamen iklimden bağımsız hale gelmiştir', false, 0);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('49b4f1d6-7ca8-4d5b-98d1-6891c1ff8512', 'Bölgede artık hiçbir sulama ihtiyacı kalmamıştır', false, 1);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('49b4f1d6-7ca8-4d5b-98d1-6891c1ff8512', 'Sulama gibi beşerî bir müdahale, kurak iklimin getirdiği doğal sınırlamayı büyük ölçüde aşabilmiştir', true, 2);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('49b4f1d6-7ca8-4d5b-98d1-6891c1ff8512', 'Bölgede artık yalnızca pamuk tarımı yapılmaktadır', false, 3);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('49b4f1d6-7ca8-4d5b-98d1-6891c1ff8512', 'Bu durum yalnızca Karadeniz Bölgesi için geçerlidir', false, 4);
insert into questions (id, topic_id, difficulty, question_text, kazanim, explanation) values ('afedcd0f-3c25-4ca8-9a85-edbcf1be8667', '307f95b7-0c09-47b4-b088-895dba797c11', 'zor'::difficulty_level, 'Marmara Bölgesi''nin Türkiye''nin en büyük sanayi merkezi olmasıyla ilgili aşağıdaki çıkarımlardan hangisi YAPILAMAZ?', 'Sanayi yoğunlaşmasının çok faktörlü nedenlerini ileri düzeyde değerlendirir.', 'Marmara''nın sanayi merkezi olması; nitelikli/ucuz iş gücü ve geniş iç pazarın varlığı (A doğru), limanlara ve ana ulaşım güzergâhlarına yakınlık (B doğru) ve sermaye birikiminin fazla olması (D doğru) gibi ÇOK FAKTÖRLÜ bir sonuçtur. C ifadesi ise YANLIŞTIR ve sorunun cevabıdır: sanayinin yoğunlaşması yalnızca ''iklimin çok elverişli olmasına'' bağlanamaz — iklim, sanayi yer seçiminde belirleyici bir faktör değildir; iş gücü, pazar, ulaşım ve sermaye çok daha belirleyicidir. E doğrudur, sanayi yoğunlaşması genellikle o bölgeye göçü ve nüfus artışını tetikler.');
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('afedcd0f-3c25-4ca8-9a85-edbcf1be8667', 'Bölgede nitelikli ve ucuz iş gücü ile geniş bir iç pazarın bulunması bu durumu açıklayan etmenlerden biridir', false, 0);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('afedcd0f-3c25-4ca8-9a85-edbcf1be8667', 'Limanlara ve ana ulaşım güzergâhlarına yakın olması bu durumu açıklayan etmenlerden biridir', false, 1);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('afedcd0f-3c25-4ca8-9a85-edbcf1be8667', 'Bu durum yalnızca ve tek başına bölgenin iklim koşullarının çok elverişli olmasıyla açıklanabilir', true, 2);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('afedcd0f-3c25-4ca8-9a85-edbcf1be8667', 'Sermaye birikiminin fazla olması bu durumu açıklayan etmenlerden biridir', false, 3);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('afedcd0f-3c25-4ca8-9a85-edbcf1be8667', 'Sanayinin yoğunlaşması bölgeye göçü tetikleyerek nüfus yoğunluğunu artırabilir', false, 4);
insert into questions (id, topic_id, difficulty, question_text, kazanim, explanation) values ('fdb1e87d-dffa-49d9-875c-0b4e408d4ba5', '307f95b7-0c09-47b4-b088-895dba797c11', 'orta'::difficulty_level, 'Türkiye''de demir yolu ulaşımının kara yoluna kıyasla yeterince gelişememesinin temel nedeni aşağıdakilerden hangisidir?', 'Ulaşım türlerinin gelişimini yer şekilleriyle ilişkilendirir.', 'Türkiye arazisinin engebeli olması ve dağların kıyıya paralel uzanması, demir yolu güzergâhlarında çok sayıda tünel ve viyadük gerektirerek maliyeti artırmış, bu da demir yolunun kara yoluna göre yeterince gelişememesine yol açmıştır (C doğru). Nüfusun az olması (A) ve sanayinin gelişmemiş olması (B) Türkiye geneli için gerçeği yansıtmaz. Petrol/doğal gaz kaynaklarının bolluğu (D) ulaşım türü tercihini değil enerji politikalarını ilgilendirir. İklimin çok elverişli olması (E) demir yolu gelişimini engelleyen bir etmen değildir, konuyla ters bir ilişki kurar.');
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('fdb1e87d-dffa-49d9-875c-0b4e408d4ba5', 'Türkiye''de nüfusun çok az olması', false, 0);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('fdb1e87d-dffa-49d9-875c-0b4e408d4ba5', 'Sanayinin ülke genelinde hiç gelişmemiş olması', false, 1);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('fdb1e87d-dffa-49d9-875c-0b4e408d4ba5', 'Arazinin engebeli olması ve dağların kıyıya paralel uzanmasının maliyeti artırması', true, 2);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('fdb1e87d-dffa-49d9-875c-0b4e408d4ba5', 'Petrol ve doğal gaz kaynaklarının çok bol olması', false, 3);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('fdb1e87d-dffa-49d9-875c-0b4e408d4ba5', 'İklimin demir yolu yapımı için çok elverişli olması', false, 4);
